update public.learning_paths
set
  title = 'Lifecycle Nutrition',
  goal = 'Lifecycle Nutrition',
  summary = 'This course examines nutritional requirements, feeding relationships, dietary patterns, assessment, counseling, and public-health context from preconception through older adulthood. Students integrate physiology and development with culture, family systems, food access, disability, activity, chronic-disease risk, and care settings. Cases emphasize safe, evidence-informed, culturally responsive planning within the undergraduate dietetics scope, including recognition of red flags requiring referral or medical nutrition therapy.',
  data = $lcnjson${"slug": "lifecycle-nutrition", "title": "Lifecycle Nutrition", "description": "This course examines nutritional requirements, feeding relationships, dietary patterns, assessment, counseling, and public-health context from preconception through older adulthood. Students integrate physiology and development with culture, family systems, food access, disability, activity, chronic-disease risk, and care settings. Cases emphasize safe, evidence-informed, culturally responsive planning within the undergraduate dietetics scope, including recognition of red flags requiring referral or medical nutrition therapy.", "topics": [{"id": "d5e20d8d-3c25-4627-8d4b-a7f357339591", "type": "topic", "title": "Life-Course Nutrition Frameworks and Evidence", "description": "Introduces nutrition as a changing interaction among biology, development, behavior, family, environment, culture, policy, and cumulative exposures. Students learn to interpret evidence without turning population guidance into individualized medical advice.", "children": [{"id": "fb41e3d5-07e7-4449-bbfe-004d7982f2d8", "type": "subtopic", "title": "Life-course perspective", "description": "Understand how timing, transitions, and accumulated exposures shape later health.", "children": [{"id": "b46f7696-820d-4f85-aaea-d9d774823e83", "type": "concept", "title": "Critical and sensitive periods"}, {"id": "b38e7423-524d-4245-9f3a-fd5443a6e777", "type": "concept", "title": "Developmental origins of health and disease"}, {"id": "7eb98d21-e37b-47bd-a17b-4fff9b5adff5", "type": "concept", "title": "Tracking, transitions, resilience, and intergenerational effects"}]}, {"id": "52dd4c35-5cbe-451a-bd30-fef70731dbb2", "type": "subtopic", "title": "Nutrient standards and guidance", "description": "Use reference values correctly and explain their limits.", "children": [{"id": "eb4295cc-5308-4dc8-bf6f-626fcc0b3b4b", "type": "concept", "title": "EAR, RDA, AI, UL, AMDR, and energy requirements"}, {"id": "23e9e300-9a6f-4678-8388-a44737f15d75", "type": "concept", "title": "Food-based dietary guidance and dietary patterns"}, {"id": "c12c5c55-622a-4f9f-8044-775c1123a026", "type": "concept", "title": "Population standards versus individualized clinical care"}]}, {"id": "563d160f-d836-403e-8843-6cc7d35bf5ae", "type": "subtopic", "title": "Evidence appraisal", "description": "Distinguish stronger causal evidence from association and mechanistic plausibility.", "children": [{"id": "a847e34f-8c2b-4fd7-9c6a-8a5fbe768cea", "type": "concept", "title": "Study design, confounding, bias, and generalizability"}, {"id": "f257d9b3-d455-4790-ad3d-f13b4f0a70c9", "type": "concept", "title": "Systematic reviews, guidelines, and evidence grading"}, {"id": "85310ed7-95f2-4bbf-a94f-a34aa2fc860c", "type": "concept", "title": "Absolute risk, uncertainty, conflicts of interest, and evolving recommendations"}]}]}, {"id": "79089e31-84ea-40cd-afc2-b60e3e535eba", "type": "topic", "title": "Lifecycle Nutrition Assessment and Growth", "description": "Builds an age-appropriate assessment process using anthropometry, diet, clinical context, biochemistry, function, and social determinants. No single measure is interpreted in isolation.", "children": [{"id": "42cca67a-c202-4822-8a9c-0b0e69f67e26", "type": "subtopic", "title": "Anthropometry and growth", "description": "Measure and interpret body size and change with appropriate reference standards.", "children": [{"id": "2b07f338-287d-4bd5-bfcf-d59b5daa5478", "type": "concept", "title": "Weight, length/height, BMI, head circumference, and body composition"}, {"id": "15e8156b-9062-4dd3-bd6f-8460c7019b6d", "type": "concept", "title": "Growth charts, percentiles, z-scores, trajectories, and measurement error"}, {"id": "319c7757-eb25-4632-93ec-467c8bc4e839", "type": "concept", "title": "Growth faltering, rapid gain, edema, sarcopenia, and referral triggers"}]}, {"id": "83423d7a-f626-4e19-b495-1a31c8d2de02", "type": "subtopic", "title": "Dietary and feeding assessment", "description": "Match methods to age, cognitive capacity, and decision need.", "children": [{"id": "550b7cba-dd4a-407f-a572-f304ad90dd6f", "type": "concept", "title": "24-hour recall, records, screeners, FFQ, and usual-intake concepts"}, {"id": "82aa7e80-2e2e-4427-a59e-89ce6031b1d5", "type": "concept", "title": "Breast/chestfeeding, complementary feeding, school, workplace, and care-setting context"}, {"id": "8360e8c1-20bf-46b8-85e8-6cc8c0437ef0", "type": "concept", "title": "Supplements, fortified foods, beverages, feeding skills, and meal patterns"}]}, {"id": "d004c9b3-550c-4efd-a6f9-60dca66288cf", "type": "subtopic", "title": "Integrated assessment", "description": "Synthesize findings while avoiding weight stigma and diagnostic overreach.", "children": [{"id": "9d1c4b1e-0c93-4388-aadb-8d6209610f81", "type": "concept", "title": "Biochemical, clinical, functional, medication, and symptom data"}, {"id": "7918b273-406f-44a4-a8f8-01e4f39fffd4", "type": "concept", "title": "Food security, access, culture, caregiving, housing, and resources"}, {"id": "fb6cc6c7-863a-4150-95b8-e77768d9aced", "type": "concept", "title": "Nutrition-focused physical findings and interprofessional referral"}]}]}, {"id": "10335215-aa5e-4651-8bff-a952682edce9", "type": "topic", "title": "Preconception and Reproductive Nutrition", "description": "Frames nutrition before conception as relevant to fertility, pregnancy readiness, chronic disease, medication safety, and intergenerational health for people of all genders.", "children": [{"id": "c86e9a89-cc96-47c5-9afe-189d74f02f7a", "type": "subtopic", "title": "Preconception foundations", "description": "Identify modifiable factors while respecting autonomy and diverse reproductive goals.", "children": [{"id": "bfb06916-6518-4cd5-9c94-f78b42af058b", "type": "concept", "title": "Nutrient adequacy, dietary pattern, physical activity, sleep, and substance exposure"}, {"id": "f2f4b36d-657e-4e4b-b245-38942a9e35d8", "type": "concept", "title": "Folate, iron,